SELECT `imp`.`id` as productId, `imp`.`prod_name` AS `productName`, COUNT(`cbd`.id) as deviceCount FROM `iot_md_product` `imp` left join `center_biz_device` `cbd` on (cbd.device_iot_prod_id = imp.id)
imp.id in
#{productId}
